uniform float amzp_strength;
uniform float amzp_intensity;
uniform float amzp_threshold;
uniform float2 amzp_glowStretch;
uniform float amzp_galpha;
uniform float amzp_alpha;
         float3 toLinear(float3 c, float g) {
                 return pow(c, float3(g));
         }
         float3 toSRGB(float3 c, float g) {
                 return pow(c, float3(1.0 / g));
         }
         float4 blurInternal(int tex, float2 texOffset, float2 st, float numBlurPixelsPerSide, float2 aspectRatio) {
                 if (amzp_strength <= 0.0) return float4(0.0);
                 texOffset *= float2(amzp_glowStretch.x, (amzp_glowStretch.y +0.5));
                 texOffset *= aspectRatio;
