                 float gray = dot(color, float3(0.299, 0.587, 0.114));
                 return mix(float3(gray), color, 1.0 + amount);
         }
         float3 applyDeepGlow(float3 glow, float4 tint, float falloffFactor, float gamma) {
                 float3 linearGlow = toLinear(glow, gamma);
                 linearGlow *= 1.0 / (1.0 + falloffFactor * length(linearGlow));
                 linearGlow *= tint.rgb;
                 linearGlow *= tint.a;
                 return toSRGB(linearGlow, gamma);
         }
