                 float2 uv = amzScreenNorm().st;
                 float2 aspect = float2(screen.zw.x / screen.zw.y, 1.0);
                 if (amzPass == 0) {
                 float4 color = amzTexture(0, uv);
                 float luminance = dot(color.rgb, float3(0.299, 0.587, 0.114));
                 float mask = smoothstep(amzp_threshold, amzp_threshold + 0.05, luminance);
                 float3 highlight = color.rgb * mask;
                 amzOutput = float4(highlight, 1.0);
                 } else if (amzPass == 1) {
                         float kernelSize = amzp_strength / 2.0 * 1.14 / 4.0 / 3.0 * length(screen.zw);
                         float2 texOffset = float2(1.0 / (screen.zw/2.0).x, 0.0);
                         amzOutput = blurInternal(1, texOffset, uv, kernelSize, aspect);
                 } else if (amzPass == 2) {
                         float kernelSize = amzp_strength / 2.0 * 1.14 / 4.0 / 3.0 * length(screen.zw);
                         float2 texOffset = float2(0.0, 1.0 / (screen.zw/2.0).y);
                         amzOutput = blurInternal(2, texOffset, uv, kernelSize, aspect);
                  } else if (amzPass == 3) {
                  float2 center = float2(0.5, 0.5);
                  float2 expandedUV = mix(uv, center, 0.0);
                  float4 baseColor = amzTexture(0, uv);
                  float3 bloomColor = amzTexture(3, expandedUV).rgb * amzp_intensity;
                  float bloomAlpha = amzTexture(3, expandedUV).a;
                  float3 finalGlow = float3(0.0);
                                  finalGlow = boostSaturation(bloomColor, 0.0);
                         float3 result = (baseColor.rgb * amzp_alpha) + (finalGlow * amzp_galpha);
                         amzOutput = float4(result, baseColor.a);
                  }
         }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

